    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // We add a penalty for "Dead Space" (post_residual < 10) that is too small to accommodate 
    // most items, unless it's a perfect fit (0).
    let mut score = post * (1.0 + 0.5 * (post < 10.0 && post > 0.0) as i32 as f64);

    // Lookahead logic: If next_item_size is large, avoid creating a post_residual that is 
    // too small to fit the upcoming item.
    if next_item_size > 0 {
        let lookahead_penalty = if post < next_item_size as f64 {
            (next_item_size as f64 - post) * 1.5
        } else {
            -(post - next_item_size as f64) * 0.2
        };
        score += lookahead_penalty;
    }

    // Dynamic thresholding based on stream progress:
    // As we approach the end of the stream, prioritize closing bins (lower mean_residual) 
    // over maintaining perfect fit balance.
    let closure_incentive = (mean_residual - post) * progress;
    score -= closure_incentive;

    // Penalty for opening a new bin:
    // Only open a new bin if the current bin's post_residual is poor relative to 
    // the mean_residual or if we are early in the stream.
    if res == bin_capacity as f64 {
        score += 25.0 - (progress * 10.0) + (open_bins_count as f64 * 0.5);
    }

    // Favor bins that have less space remaining as we fill them up, 
    // but penalize bins that are left with "awkward" gaps (10-20 range).
    if post > 10.0 && post < 20.0 {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #151: Harmonic Class & Lookahead-Aware Residual Minimization
    // We aim to minimize the post_residual while penalizing "fragmentation"
    // that makes it impossible to fit common future items (lookahead).

    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // 1. Base Score: Minimize residual (Best Fit principle)
    let mut score = post;

    // 2. Harmonic Fragmentation Penalty: 
    // Penalize residuals that are small but not zero, specifically those 
    // that cannot fit the next item.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            // Penalize hard if this bin won't fit the next item
            score += (next_item_size as f64 - post) * 1.5;
        } else {
            // Reward if the bin can accommodate the next item (synergy)
            score -= (next_item_size as f64) * 0.8;
        }
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (residual == capacity), penalize based on 
    // how many bins are already open to prevent premature bin opening.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
        // If other bins can fit the item, make the new bin very unattractive
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // 4. Mean Residual Balancing:
    // Avoid creating bins that deviate significantly from the mean state 
    // of the system to maintain uniform packing density.
    let dev = (post - mean_residual).abs();
    score += dev * 0.2;

    // 5. Harmonic Class Logic: 
    // Favor residuals that are multiples of common item sizes (e.g., 20, 25).
    // Penalize values that result in "orphaned" space (e.g., 1-9).
    if post < 10.0 && post > 0.0 {
        score += 20.0;
    }

    score
}

