    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize smaller post-residual (Best Fit principle)
    // We penalize larger post_residuals quadratically to favor tight packing.
    let mut score = post_res.powf(1.5);

    // Lookahead logic: If the next item is large, avoid leaving a small, unusable gap.
    // If post_residual is smaller than next_item_size, it creates "dead space".
    if next_item_size > 0 {
        if post_res < next_item_size as f64 {
            score += (next_item_size as f64 - post_res).powf(2.0) * 0.8;
        }
    }

    // Dynamic pressure: As the stream progresses, increase the penalty for opening new bins.
    // We treat the "new bin" candidate (where bin_residual == bin_capacity) specially.
    if bin_residual == bin_capacity {
        // The cost of opening a new bin grows as we reach the end of the stream
        // to encourage consolidating items into existing bins.
        score += 40.0 + (progress * 60.0);
    } else {
        // If the bin is already open, slightly favor bins that have a smaller-than-average residual
        // to keep the "most full" bins filling up first (Best Fit).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0 * (1.0 - progress);
        }

        // If this is the only bin that can fit the item, give it a significant boost
        // to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    score
}

