    // avoid it if it leaves a very awkward space (e.g., < 10), unless the item is large.
    if fitting_bins_count == 1 && post_residual < 15 && post_residual > 0 {
        score += 30.0;
    }

    // 4. Mean-residual balancing: If the post_residual is significantly better than the
    // global mean, reward it to encourage tight packing across all bins.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. New bin thresholding: Make opening a new bin expensive unless the current
    // options are extremely poor (post_residual > 20).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the best available fit is worse than 25 units.
            score = 25.0;
        }
    }

    // 6. Progression scaling: As we reach the end of the stream, prioritize
    // closing bins (lower post_residual) more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
